      "content": "{\n  \"name\": \"@wxg-prc-cpg/browser-skill-dsh-plugin\",\n  \"description\": \"DeepSeek Harness tool plugin that exposes BrowserSkill browser automation (bsk_* tools) to the model\",\n  \"version\": \"0.4.0\",\n  \"license\": \"MIT\",\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Tencent/BrowserSkill.git\",\n    \"directory\": \"packages/dsh-plugin-browserskill\"\n  },\n  \"homepage\": \"https://github.com/Tencent/BrowserSkill/tree/main/packages/dsh-plugin-browserskill#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Tencent/BrowserSkill/issues\"\n  },\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"browserskill\",\n    \"browser-automation\"\n  ],\n  \"type\": \"module\",\n  \"main\": \"lib/index.mjs\",\n  \"types\": \"lib/index.d.mts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.mts\",\n      \"default\": \"./lib/index.mjs\"\n    },\n    \"./client\": {\n      \"default\": \"./lib/client.cjs\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"skill\",\n    \"cordis.patch.yml\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-tool\",\n        \"@deepseek-ai/dsh-client-ui-layout\"\n      ],\n      \"external\": [\n        \"@deepseek-ai/dsh-client-ui-primitives\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/build-client-css.mjs && node scripts/build-skill-content.mjs && tsdown\",\n    \"typecheck\": \"pnpm run build:skill && tsc --noEmit\",\n    \"test\": \"pnpm run build:css && pnpm run build:skill && vitest run\",\n    \"build:css\": \"node scripts/build-client-css.mjs\",\n    \"build:skill\": \"node scripts/build-skill-content.mjs\",\n    \"prepack\": \"pnpm run build\",\n    \"lint:publint\": \"publint\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh-attachment\": \"^0.1.5-rc.3 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.1.5-rc.3 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-tool\": \"^0.1.5-rc.3 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.5-rc.3 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.5-rc.3 || ^0.2.0-rc.1\",\n    \"@deepseek-ai/schemastery\": \"^3.18.2\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-attachment\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-tool\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@browser-skill/ui\": \"workspace:*\",\n    \"@deepseek-ai/cordis\": \"4.0.2\",\n    \"@deepseek-ai/dsh-agent\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-agent-loop\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-attachment\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-client-store\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-chat\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-client-ui-tool\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-llm\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-scope\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-session\": \"0.1.5-rc.3\",\n    \"@deepseek-ai/dsh-session-projection