    {
      "path": "packages/dsh-plugin-browserskill/src/runner.ts",
      "content": "/**\n * Process runner for the `bsk` CLI. Every model-facing tool in this plugin\n * maps to one `bsk <cmd> --json` invocation: spawn the child, capture\n * stdout/stderr, honor the dsh cancellation signal by killing the child, and\n * map the CLI's JSON error envelope onto a thrown `BskError`.\n */\n\nimport { type ChildProcess, type SpawnOptionsWithoutStdio, spawn } from \"node:child_process\";\nimport { StringDecoder } from \"node:string_decoder\";\n\n/** Shape of the JSON error envelope `bsk --json` prints on failure. */\nexport interface BskErrorBody {\n  code?: string;\n  message?: string;\n  hint?: string;\n  exit_code?: number;\n  data?: unknown;\n}\n\n/** A failed `bsk` invocation (non-zero exit, timeout, or spawn failure). */\nexport class BskError extends Error {\n  readonly code?: string;\n  readonly hint?: string;\n  readonly exitCode?: number | null;\n  readonly timedOut: boolean;\n  readonly data?: unknown;\n\n  constructor(\n    message: string,\n    options: {\n      code?: string;\n      hint?: string;\n      exitCode?: number | null;\n      timedOut?: boolean;\n      data?: unknown;\n    } = {},\n  ) {\n    super(message);\n    this.name = \"BskError\";\n    this.code = options.code;\n    this.hint = options.hint;\n    this.exitCode = options.exitCode;\n    this.timedOut = options.timedOut ?? false;\n    this.data = options.data;\n  }\n}\n\nexport interface BskRunResult {\n  /** Process exit code, or null when killed by a signal / never started. */\n  code: number | null;\n  stdout: string;\n  stderr: string;\n  timedOut: boolean;\n  aborted: boolean;\n}\n\nexport interface BskRunOptions {\n  signal?: AbortSignal;\n  /** Execution timeout; after exit, output collection has a separate 2s limit. */\n  timeoutMs?: number;\n  /** Opaque routing tag (e.g. a session id) enabling per-tag kills. */\n  tag?: string;\n}\n\n/** Minimal spawn signature so tests can substitute a fake child process. */\nexport type SpawnImpl = (\n  command: string,\n  args: string[],\n  options?: SpawnOptionsWithoutStdio,\n) => ChildProcess;\n\nexport interface BskRunner {\n  /** Run `bsk <args...> --json` and collect its output. */\n  run(args: string[], options?: BskRunOptions): Promise<BskRunResult>;\n  /** Kill every still-running child (used when the plugin unloads). */\n  killAll(): void;\n  /** Kill running children carrying this tag; returns the number matched. */\n  killFor(tag: string): number;\n}\n\n// Business RPCs translate Ctrl-C / opt-in stdin EOF into cancel(rpc_id).\n// Allow reconciliation before hard-killing an old or unresponsive CLI.\nexport const KILL_GRACE_MS = 3000;\n// Windows IPC may spend 5s connecting, 2s cancelling, 2s settling,\n// and up to 5s releasing the entire batch of caller-owned transfers.\nexport const WINDOWS_KILL_GRACE_MS = 15_000;\n// A killed child that never reports `exit` at all must still release the caller\n// once the forced kill has had its chance.\nexport const SETTLE_AFTER_KILL_SLACK_MS = 1000;\n// `close` fires only once every stdio pipe has reached EOF, which needs every\n// process holding a copy of the pipe handles to be gone, not just `bsk`. When\n// `bsk` auto-spawns the daemon, the daemon can end up holding those handles\n// (Windows `CreateProcess` inherits every inheritable handle; issue #180), so\n// after `exit` we drain what the pipes still give us and then settle, rather\n// than waiting for a `close` that may never come. `close` normally follows\n// `exit` within the same loop turn, so the wait is only ever paid when\n// something else is holding the pipes. Bytes arriving inside the window can\n// still be the child's own buffered output, so every chunk restarts the window\n// and EXIT_DRAIN_MAX_MS caps the total wait.\nconst EXIT_DRAIN_GRACE_MS = 1000;\nconst EXIT_DRAIN_MAX_MS = 2000;\nconst SESSION_BUSY_RETRY_DELAY_MS = 100;\n\n/** One in-flight child plus the bounded shutdown that settles its run. */\ninterface LiveRun {\n  tag: string | undefined;\n  requestKill: () => boolean;\n}\n\nexport function createBskRunner(bskPath: string, spawnImpl: SpawnImpl = spawn): BskRunner {\n  const live = new Map<ChildProcess, LiveRun>();\n  const windows = process.platform === \"win32\";\n  const cancelling = new Map<ChildProcess, ReturnType<typeof setTimeout>>();\n  const killGraceMs = windows ? WINDOWS_KILL_GRACE_MS : KILL_GRACE_MS;\n  // The kill grace and the settlement deadline stay in step: a Windows\n  // cancellation using its full 15s must not be cut short by a 4s fallback.\n  const settleAfterKillMs = killGraceMs + SETTLE_AFTER_KILL_SLACK_MS;\n\n  function killChild(child: ChildProcess): void {\n    if (child.exitCode !== null || child.signalCode !== null || cancelling.has(child)) return;\n    const force = setTimeout(() => {\n      if (child.exitCode === null && child.signalCode === null) child.kill(\"SIGKILL\");\n    }, killGraceMs);\n    force.unref();\n    cancelling.set(child, force);\n    // Node kills Windows children outright for SIGINT. EOF asks the CLI to\n    // send its existing cancel RPC and wait for browser reconciliation.\n    if (windows && child.stdin) child.stdin.end();\n    else child.kill(\"SIGINT\");\n  }\n\n  return {\n    run(args, options = {}) {\n      if (options.signal?.aborted) {\n        return Promise.resolve({\n          code: null,\n          stdout: \"\",\n          stderr: \"\",\n          timedOut: false,\n          aborted: true,\n        });\n      }\n      return new Promise<BskRunResult>((resolve, reject) => {\n        let child: ChildProcess;\n        try {\n          child = spawnImpl(\n            bskPath,\n            [...args, \"--json\"],\n            windows\n              ? {\n                  windowsHide: true,\n                  env: { ...process.env, BSK_CANCEL_ON_STDIN_CLOSE: \"1\" },\n                }\n              : undefined,\n          );\n          // A child exiting while cancellation closes stdin may report EPIPE.\n          // Process completion remains the authority for the run result.\n          child.stdin?.on(\"error\", () => {});\n        } catch (error) {\n          reject(error);\n          return;\n        }\n\n        let stdout = \"\";\n        let stderr = \"\";\n        const stdoutDecoder = new StringDecoder(\"utf8\");\n        const stderrDecoder = new StringDecoder(\"utf8\");\n        let timedOut = false;\n        let aborted = false;\n        const onStdout = (chunk: Buffer | string) => {\n          stdout += stdoutDecoder.write(typeof chunk === \"string\" ? Buffer.from(chunk) : chunk);\n          extendDrain();\n        };\n        const onStderr = (chunk: Buffer | string) => {\n          stderr += stderrDecoder.write(typeof chunk === \"string\" ? Buffer.from(chunk) : chunk);\n          extendDrain();\n        };\n        child.stdout?.on(\"data\", onStdout);\n        child.stderr?.on(\"data\", onStderr);\n\n        let settled = false;\n        let deadline: ReturnType<typeof setTimeout> | undefined;\n        let drainWindow: ReturnType<typeof setTimeout> | undefined;\n        let drainCap: ReturnType<typeof setTimeout> | undefined;\n        let drainCode: number | null = null;\n        // Dropping the listeners stops the collection, but our ends of the pipes\n        // stay open and keep the event loop referenced. When a grandchild holds\n        // the other ends, that would keep the host alive long after the run has\n        // settled, so close them and stop waiting on the child itself.\n        const release = () => {\n          child.stdout?.off(\"data\", onStdout);\n          child.stderr?.off(\"data\", onStderr);\n          child.stdout?.destroy();\n          child.stderr?.destroy();\n          child.stdin?.destroy();\n          child.unref();\n        };\n        const finish = (code: number | null) => {\n          if (settled) return;\n          settled = true;\n          stdout += stdoutDecoder.end();\n          stderr += stderrDecoder.end();\n          settle();\n          release();\n          resolve({ code, stdout, stderr, timedOut, aborted });\n        };\n        // Wait for `close` after a normal `exit`, but not forever. Output landing\n        // in the window can still be the child's own buffered bytes, so each\n        // chunk reopens it for another EXIT_DRAIN_GRACE_MS and the cap keeps the\n        // total bounded when whatever holds the pipes keeps writing.\n        const extendDrain = () => {\n          if (drainCap === undefined || settled) return;\n          if (drainWindow !== undefined) clearTimeout(drainWindow);\n          drainWindow = setTimeout(() => finish(drainCode), EXIT_DRAIN_GRACE_MS);\n        };\n        const beginDrain = (code: number | null) => {\n          if (drainCap !== undefined) return;\n          drainCode = code;\n          // Keep the drain referenced if exit released the last process handle.\n          drainCap = setTimeout(() => finish(code), EXIT_DRAIN_MAX_MS);\n          extendDrain();\n        };\n        // Kill on our own initiative, then guarantee the promise settles even if\n        // the child never reports back: `exit` normally arrives promptly, and the\n        // deadline covers a child that reports nothing at all after SIGKILL.\n        const requestKill = () => {\n          // An exited command may still be draining its result. An interrupt\n          // cannot stop it anymore and must not discard the remaining output.\n          if (settled || child.exitCode !== null || child.signalCode !== null) return false;\n          killChild(child);\n          if (!settled && deadline === undefined) {\n            deadline = setTimeout(() => finish(child.exitCode), settleAfterKillMs);\n            deadline.unref();\n          }\n          return true;\n        };\n        live.set(child, { tag: options.tag, requestKill });\n\n        const timeoutMs = options.timeoutMs;\n        const timer =\n          timeoutMs !== undefined && timeoutMs > 0\n            ? setTimeout(() => {\n                if (child.exitCode !== null || child.signalCode !== null) return;\n                timedOut = true;\n                requestKill();\n              }, timeoutMs)\n            : undefined;\n        timer?.unref();\n\n        const onAbort = () => {\n          if (settled) return;\n          // A step that already exited normally has finished its work. A late\n          // abort must not discard its receipt while stdout is still draining.\n          if (args[0] === \"step\" && child.exitCode !== null && child.signalCode === null) return;\n          aborted = true;\n          // Explicit cancellation also stops waiting for an exited child's output.\n          if (!requestKill()) finish(child.exitCode);\n        };\n        const clearCancellationTimers = () => {\n          if (deadline !== undefined) {\n            clearTimeout(deadline);\n            deadline = undefined;\n          }\n          const force = cancelling.get(child);\n          if (force !== undefined) clearTimeout(force);\n          cancelling.delete(child);\n        };\n        const settle = () => {\n          if (timer !== undefined) clearTimeout(timer);\n          clearCancellationTimers();\n          if (drainWindow !== undefined) clearTimeout(drainWindow);\n          if (drainCap !== undefined) clearTimeout(drainCap);\n          options.signal?.removeEventListener(\"abort\", onAbort);\n          child.off(\"exit\", onExit);\n          child.off(\"close\", finish);\n          live.delete(child);\n        };\n\n        const onExit = (code: number | null, signal: NodeJS.Signals | null) => {\n          // Execution is over; output collection has its own bounded deadline.\n          // Retire forced-kill settlement so it cannot truncate the drain window.\n          if (timer !== undefined) clearTimeout(timer);\n          clearCancellationTimers();\n          if (signal !== null || timedOut || (aborted && args[0] !== \"step\")) {\n            finish(code);\n            return;\n          }\n          // A gracefully cancelled step can still report completed action\n          // evidence. Collect its buffered receipt under the same drain cap.\n          // Normal exit: keep draining while bytes are still arriving, then\n          // settle even if a grandchild is still holding the pipes open.\n          beginDrain(code);\n        };\n\n        child.on(\"error\", (error) => {\n          if (settled) return;\n          settled = true;\n          settle();\n          release();\n          reject(error);\n        });\n        child.on(\"close\", finish);\n        child.once(\"exit\", onExit);\n        if (options.signal?.aborted) {\n          onAbort();\n        } else {\n          options.signal?.addEventListener(\"abort\", onAbort, { once: true });\n        }\n      });\n    },\n    killAll() {\n      for (const run of live.values()) run.requestKill();\n    },\n    killFor(tag: string) {\n      let killed = 0;\n      for (const run of live.values()) {\n        if (run.tag === tag && run.requestKill()) killed += 1;\n      }\n      return killed;\n    },\n  };\n}\n\n/** True when the spawn failure means the bsk binary itself is missing. */\nexport function isCommandNotFound(error: unknown): boolean {\n  return (\n    typeof error === \"object\" &&\n    error !== null &&\n    \"code\" in error &&\n    (error as { code?: unknown }).code === \"ENOENT\"\n  );\n}\n\n/** True only for the daemon's transient per-session reconciliation window. */\nexport function isSessionBusyResult(result: BskRunResult): boolean {\n  if (result.code === 0) return false;\n  try {\n    const body = JSON.parse(result.stdout) as BskErrorBody;\n    const reason =\n      typeof body.data === \"object\" && body.data !== null && \"reason\" in body.data\n        ? (body.data as { reason?: unknown }).reason\n        : undefined;\n    return reason === \"session_busy\";\n  } catch {\n    return false;\n  }\n}\n\n/**\n * Retry exactly once after the tiny daemon-settlement race that can follow a\n * graceful SIGINT cancellation. Other errors and persistent busy states stay\n * visible to callers.\n */\nexport async function runWithSessionBusyRetry(\n  run: () => Promise<BskRunResult>,\n  signal?: AbortSignal,\n): Promise<BskRunResult> {\n  const first = await run();\n  if (!isSessionBusyResult(first)) return first;\n  await abortableDelay(SESSION_BUSY_RETRY_DELAY_MS, signal);\n  return run();\n}\n\nfunction abortableDelay(ms: number, signal?: AbortSignal): Promise<void> {\n  if (signal?.aborted) return Promise.reject(abortError());\n  return new Promise((resolve, reject) => {\n    const timer = setTimeout(done, ms);\n    timer.unref();\n    const onAbort = () => {\n      clearTimeout(timer);\n      signal?.removeEventListener(\"abort\", onAbort);\n      reject(abortError());\n    };\n    function done() {\n      signal?.removeEventListener(\"abort\", onAbort);\n      resolve();\n    }\n    signal?.addEventListener(\"abort\", onAbort, { once: true });\n  });\n}\n\nfunction abortError(): Error {\n  const error = new Error(\"tool call aborted\");\n  error.name = \"AbortError\";\n  return error;\n}\n\n/** Install guidance shown when the bsk CLI cannot be spawned. */\nexport function bskInstallMessage(bskPath: string): string {\n  return (\n    `the bsk CLI (\"${bskPath}\") was not found. BrowserSkill must be installed and on PATH ` +\n    \"for browser tools to work — install it from https://github.com/Tencent/BrowserSkill \" +\n    \"(see the README install script or `cargo install`), then retry. \" +\n    `If bsk is installed at a custom location, set the plugin's \\`bskPath\\` option ` +\n    `(currently \"${bskPath}\") instead of relying on PATH.`\n  );\n}\n\n/**\n * Options for interpreting a finished `bsk` run.\n *\n * `allowNavigationTimeout`: when the CLI prints a success-shaped navigation\n * payload with `reached: \"timeout\"` and then exits 4 (RenderedExit), return\n * that payload instead of throwing. Exit 4 alone is not enough — session-busy\n * and other failures also use 4 — so the payload must explicitly say\n * `reached: \"timeout\"`.\n */\nexport interface ParseBskJsonOptions {\n  allowNavigationTimeout?: boolean;\n  /** Preserve a validated step receipt, including its unsuccessful stages.\n   * An aborted run must explicitly acknowledge cancellation; execution\n   * timeouts, killed processes and ordinary error envelopes still throw. */\n  allowStepResult?: boolean;\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === \"object\" && value !== null && !Array.isArray(value);\n}\n\nfunction nonnegativeNumber(value: unknown): value is number {\n  return typeof value === \"number\" && Number.isFinite(value) && value >= 0;\n}\n\nfunction isStepFailure(value: unknown): value is Record<string, unknown> & { exit_code: number } {\n  return (\n    isRecord(value) &&\n    typeof value.message === \"string\" &&\n    (typeof value.code === \"string\" || value.code === null) &&\n    Number.isInteger(value.exit_code) &&\n    (value.exit_code as number) > 0 &&\n    (value.exit_code as number) <= 255\n  );\n}\n\n/** Match the CLI's step receipt and its exit status, not just an `ok: false` body. */\nfunction isStepResultPayload(value: unknown, exitCode: number | null): boolean {\n  if (\n    !isRecord(value) ||\n    typeof value.ok !== \"boolean\" ||\n    value.action_replayed !== false ||\n    !Number.isInteger(value.rpc_calls) ||\n    (value.rpc_calls as number) < 1 ||\n    !isRecord(value.action) ||\n    (value.cancelled !== undefined && value.cancelled !== true) ||\n    (value.storage_error !== undefined && typeof value.storage_error !== \"string\")\n  )\n    return false;\n  const { action, readiness, post, post_error: postError } = value;\n  const cancelled = value.cancelled === true;\n  let expectedExit = 0;\n  let expectedPhase: string;\n  if (isStepFailure(action.error) && action.result === undefined) {\n    if (\n      value.rpc_calls !== 1 ||\n      !nonnegativeNumber(value.elapsed_ms) ||\n      readiness !== undefined ||\n      post !== undefined ||\n      postError !== undefined\n    )\n      return false;\n    expectedExit = action.error.exit_code;\n    expectedPhase = \"action\";\n  } else if (\n    isRecord(action.result) &&\n    Number.isSafeInteger(action.result.tab_id) &&\n    action.error === undefined &&\n    isRecord(readiness)\n  ) {\n    if (action.result.reached === \"timeout\") expectedExit = 4;\n    const readinessError = readiness.error;\n    const noWait = readiness.requested === false;\n    if (isStepFailure(readinessError)) {\n      if (readiness.requested !== undefined || readiness.satisfied !== undefined) return false;\n      expectedExit = Math.max(expectedExit, readinessError.exit_code);\n    } else if (readinessError !== undefined) {\n      return false;\n    } else if (noWait) {\n      if (readiness.satisfied !== undefined) return false;\n    } else if (typeof readiness.satisfied === \"boolean\" && Number.isSafeInteger(readiness.tab_id)) {\n      if (!readiness.satisfied) expectedExit = Math.max(expectedExit, 1);\n    } else {\n      return false;\n    }\n    if (post === undefined && postError === undefined) {\n      if (\n        !isStepFailure(readinessError) ||\n        ![\"cancelled\", \"user_aborted\"].includes(String(readinessError.code)) ||\n        value.rpc_calls !== 2 ||\n        !nonnegativeNumber(value.elapsed_ms)\n      )\n        return false;\n      expectedPhase = \"readiness\";\n    } else {\n      if (\n        (value.rpc_calls as number) < (noWait ? 2 : 3) ||\n        !isRecord(value.timing_ms) ||\n        ![\"action\", \"readiness\", \"sync\", \"total\"].every((key) =>\n          nonnegativeNumber((value.timing_ms as Record<string, unknown>)[key]),\n        )\n      )\n        return false;\n      if (isStepFailure(postError) && post === undefined) {\n        expectedExit = Math.max(expectedExit, postError.exit_code);\n      } else if (isRecord(post) && Number.isSafeInteger(post.tab_id) && postError === undefined) {\n        if (typeof post.context_id !== \"string\") {\n          if (\n            typeof post.ready !== \"boolean\" ||\n            !isRecord(post.settle) ||\n            post.settle.outcome !== \"not_ready\"\n          )\n            return false;\n          expectedExit = Math.max(expectedExit, 1);\n        }\n      } else {\n        return false;\n      }\n      expectedPhase = expectedExit === 0 ? \"observed\" : \"needs_attention\";\n    }\n  } else {\n    return false;\n  }\n  if (cancelled) {\n    expectedPhase = \"cancelled\";\n    expectedExit = 2;\n  }\n  // Storage happens after phase selection, so a failed publication can retain\n  // phase:observed while correctly returning ok:false and a nonzero exit.\n  if (value.storage_error !== undefined) expectedExit = Math.max(expectedExit, 2);\n  return (\n    value.phase === expectedPhase && value.ok === (expectedExit === 0) && exitCode === expectedExit\n  );\n}\n\n/**\n * True when stdout is a navigation/history payload whose lifecycle wait\n * expired (`reached: \"timeout\"`). Used to distinguish that soft timeout from\n * other exit-4 failures (e.g. session_busy).\n */\nexport function isNavigationLifecycleTimeoutPayload(value: unknown): value is {\n  reached: \"timeout\";\n  [key: string]: unknown;\n} {\n  return (\n    typeof value === \"object\" &&\n    value !== null &&\n    !Array.isArray(value) &&\n    (value as { reached?: unknown }).reached === \"timeout\"\n  );\n}\n\n/**\n * Interpret one finished run: throw `BskError` on timeout / non-zero exit\n * (parsing the CLI's JSON error envelope when present), otherwise parse and\n * return the stdout JSON payload.\n */\nexport function parseBskJson(\n  result: BskRunResult,\n  commandLabel: string,\n  options: ParseBskJsonOptions = {},\n): unknown {\n  if (result.timedOut) {\n    throw new BskError(`bsk ${commandLabel} timed out`, { timedOut: true });\n  }\n  const body = result.stdout.trim();\n  if (options.allowStepResult === true) {\n    let payload: unknown;\n    try {\n      payload = JSON.parse(body);\n    } catch {\n      // Ordinary malformed-output handling below preserves the original error.\n    }\n    if (\n      isStepResultPayload(payload, result.code) &&\n      (!result.aborted || (isRecord(payload) && payload.cancelled === true))\n    )\n      return payload;\n    if (result.aborted) throw abortError();\n    if (result.code === 0)\n      throw new BskError(`bsk ${commandLabel} did not produce a valid step result`, {\n        exitCode: result.code,\n      });\n  }\n  // Killed by our own interrupt (SIGINT from killFor), not by the abort path:\n  // say so instead of doubling the generic label into the message.\n  if (result.code === null && !result.aborted && !result.timedOut) {\n    throw new BskError(`bsk ${commandLabel} was interrupted (process killed)`);\n  }\n  if (result.code !== 0) {\n    // Navigate / back / forward / reload print the success-shaped body then\n    // exit 4 on lifecycle wait expiry. Callers that opt in (combined session\n    // start-with-URL) can keep the session and surface the timeout instead of\n    // treating it as a hard failure.\n    if (options.allowNavigationTimeout === true && result.code === 4) {\n      try {\n        const payload: unknown = JSON.parse(body);\n        if (isNavigationLifecycleTimeoutPayload(payload)) {\n          return payload;\n        }\n      } catch {\n        // Fall through to the normal error path.\n      }\n    }\n    let parsed: BskErrorBody | undefined;\n    try {\n      parsed = JSON.parse(body) as BskErrorBody;\n    } catch {\n      parsed = undefined;\n    }\n    const message =\n      parsed?.message ?? (result.stderr.trim() || body || `bsk ${commandLabel} failed`);\n    // Surface the envelope's actionable hint in the model-facing message; a\n    // hint the model cannot see cannot be followed.\n    let withHint = parsed?.hint !== undefined ? `${message} (hint: ${parsed.hint})` : message;\n    if (parsed?.code === \"dialog_pending\" && parsed.data !== undefined)\n      withHint += `\\nPending dialog and original operation: ${JSON.stringify(parsed.data)}`;\n    throw new BskError(`bsk ${commandLabel} failed: ${withHint}`, {\n      code: parsed?.code,\n      data: parsed?.data,\n      hint: parsed?.hint,\n      exitCode: result.code,\n    });\n  }\n  try {\n    return JSON.parse(body);\n  } catch {\n    throw new BskError(\n      `bsk ${commandLabel} did not produce JSON output: ${body.slice(0, 200) || \"(empty)\"}`,\n      { exitCode: result.code },\n    );\n  }\n}\n"
    },
    {
      "path": "packages/dsh-plugin-browserskill/src/queue.ts",
      "content": "/**\n * Per-key FIFO executor. The bsk daemon serializes commands per session (a\n * second command while one is unfinished is rejected), so every plugin\n * command — model-facing tool calls AND observation captures — funnels\n * through one queue per session. A queued task rejects early if its abort\n * signal fires before it starts; once running, cancellation is owned by the\n * task's own signal handling (the runner kills the child).\n */\n\nexport class KeyedExecutor {\n  private readonly tails = new Map<string, Promise<void>>();\n\n  /** Run `fn` after every previously queued task for `key` settled. */\n  run<T>(key: string, fn: () => Promise<T>, signal?: AbortSignal): Promise<T> {\n    const previous = this.tails.get(key) ?? Promise.resolve();\n    const task = new Promise<T>((resolve, reject) => {\n      let settled = false;\n      const onAbort = () => {\n        if (!settled) {\n          settled = true;\n          reject(abortError());\n        }\n      };\n      signal?.addEventListener(\"abort\", onAbort, { once: true });\n      void previous.then(() => {\n        if (settled) return;\n        if (signal?.aborted) {\n          settled = true;\n          reject(abortError());\n          return;\n        }\n        // Running now: cancellation flows through the task's own signal.\n        signal?.removeEventListener(\"abort\", onAbort);\n        fn().then(\n          (value) => {\n            settled = true;\n            resolve(value);\n          },\n          (error: unknown) => {\n            settled = true;\n            reject(error);\n          },\n        );\n      });\n    });\n    // The stored tail never rejects, so one failure never strands the queue;\n    // and it chains BOTH the previous tail and this task, so a task aborted\n    // while still queued cannot let a later task overlap the one before it.\n    const tail = Promise.allSettled([previous, task]).then(() => {});\n    this.tails.set(key, tail);\n    // Drop the entry once the queue drains, so the map tracks live keys only.\n    void tail.then(() => {\n      if (this.tails.get(key) === tail) this.tails.delete(key);\n    });\n    return task;\n  }\n}\n\nfunction abortError(): Error {\n  const error = new Error(\"tool call aborted\");\n  error.name = \"AbortError\";\n  return error;\n}\n"
    },
    {
      "path": "packages/dsh-plugin-browserskill/src/session-starts.ts",
      "content": "import { randomUUID } from \"node:crypto\";\nimport {\n  bskInstallMessage,\n  isCommandNotFound,\n  parseBskJson,\n  runWithSessionBusyRetry,\n} from \"./runner\";\nimport { memoryStartJournal, type StartJournal, type StartRecord } from \"./start-journal\";\nimport type { ToolDeps } from \"./tools\";\n\ninterface RequestStatus {\n  state:\n    | \"prepared\"\n    | \"unknown\"\n    | \"starting\"\n    | \"ready\"\n    | \"active\"\n    | \"cancelling\"\n    | \"cleanup_failed\"\n    | \"closed\"\n    | \"failed\";\n  session?: { session_id: string; browser_instance_id: string } | null;\n  cleanup_error?: string | null;\n}\n\nexport interface StopOptions {\n  sessionId?: string;\n  /** Exact target for recovery, including starts that never returned a session ID. */\n  requestId?: string;\n  signal?: AbortSignal;\n}\n\nexport interface StopResult {\n  stopped: string;\n  requestId: string;\n  alreadyClosed: boolean;\n}\n\n/** The one lifecycle owner for pending, live, and failed-cleanup starts. */\nexport class SessionStarts {\n  private closing = false;\n  private timer?: ReturnType<typeof setTimeout>;\n  private readonly cleaning = new Map<string, Promise<void>>();\n  private readonly reserved = new Set<string>();\n\n  constructor(\n    private readonly deps: ToolDeps,\n    readonly journal: StartJournal = memoryStartJournal(),\n  ) {}\n\n  begin(owners: string[]): StartRecord {\n    if (this.closing) throw new Error(\"browser plugin is unloading\");\n    const archived = this.deps.ctx.get(\"workspaceRegistry\") as\n      | { archivedSessionIds?: string[] }\n      | undefined;\n    // The caller is first; ancestors own cleanup but do not block new starts.\n    const caller = owners[0];\n    if (caller !== undefined && archived?.archivedSessionIds?.includes(caller))\n      throw new Error(\"browser conversation is archived\");\n    // Recovered requests may still own windows even without a returned session\n    // ID. Count them before admitting more work into this plugin's capacity.\n    const recoveredPending = [...this.journal.records.values()].filter(\n      (r) =>\n        r.stop !== \"closed\" && !this.reserved.has(r.requestId) && !this.ownsRegisteredSession(r),\n    ).length;\n    this.deps.registry.reserveStart(recoveredPending);\n    const record: StartRecord = {\n      requestId: `${Date.now() + 5 * 60_000}:${randomUUID()}`,\n      owners,\n      startedAtMs: Date.now(),\n      cleanup: false,\n    };\n    this.reserved.add(record.requestId);\n    this.journal.records.set(record.requestId, record);\n    try {\n      this.journal.save();\n    } catch (error) {\n      this.forget(record);\n      throw error;\n    }\n    return record;\n  }\n\n  async prepare(record: StartRecord, signal: AbortSignal): Promise<void> {\n    try {\n      const result = await this.deps.runner.run(\n        [\"session\", \"request\", record.requestId, \"--prepare\"],\n        { signal, timeoutMs: 30_000 },\n      );\n      if (signal.aborted || result.aborted)\n        throw new DOMException(\"tool call aborted\", \"AbortError\");\n      const status = parseBskJson(result, \"session request prepare\") as RequestStatus;\n      if (status.state !== \"prepared\")\n        throw new Error(\"Browser start preparation failed; use matching CLI and daemon versions.\");\n      this.assertStarting(record);\n    } catch (error) {\n      // No start has been sent. An independently accepted stop still owns its\n      // cancellation job/receipt; a late prepare must not discard that intent.\n      if (!record.cleanup && !record.stop) this.forget(record);\n      if (isCommandNotFound(error)) throw new Error(bskInstallMessage(this.deps.config.bskPath));\n      throw error;\n    }\n  }\n\n  assertStarting(record: StartRecord): void {\n    if (\n      this.closing ||\n      record.cleanup ||\n      record.stop ||\n      !this.journal.records.has(record.requestId)\n    )\n      throw new Error(\"browser start was cancelled during cleanup\");\n  }\n\n  register(record: StartRecord, reply: { session_id: string; browser_instance_id: string }): void {\n    this.assertStarting(record);\n    if (typeof reply.session_id !== \"string\" || typeof reply.browser_instance_id !== \"string\")\n      throw new Error(\"invalid browser start result\");\n    record.session = { sessionId: reply.session_id, browserInstanceId: reply.browser_instance_id };\n    this.journal.save();\n    this.adopt(record);\n  }\n\n  private adopt(record: StartRecord): void {\n    if (!record.session) return;\n    if (this.deps.registry.isOwned(record.session.sessionId)) {\n      if (this.ownsRegisteredSession(record)) return;\n      throw new Error(\"browser session id conflicts with another owned start\");\n    }\n    if (!this.reserved.has(record.requestId)) this.deps.registry.reserveStart();\n    this.deps.registry.trackStart(\n      {\n        ...record.session,\n        requestId: record.requestId,\n        startedAtMs: record.startedAtMs,\n      },\n      record.cleanup ? \"cleanup\" : \"starting\",\n    );\n    this.reserved.delete(record.requestId);\n    this.deps.registry.trackOwner(record.session.sessionId, record.owners);\n    this.deps.observation.addSession(record.session.sessionId);\n  }\n\n  async claim(record: StartRecord, signal: AbortSignal): Promise<void> {\n    this.assertStarting(record);\n    if (!record.session || !this.ownsRegisteredSession(record))\n      throw new Error(\"browser start must be registered before claiming it\");\n    const result = await this.deps.runner.run([\"session\", \"request\", record.requestId, \"--claim\"], {\n      timeoutMs: 30_000,\n      signal,\n    });\n    if (signal.aborted || result.aborted) throw new DOMException(\"tool call aborted\", \"AbortError\");\n    const status = parseBskJson(result, \"session request\") as RequestStatus;\n    if (status.state !== \"active\") throw new Error(\"browser start could not be claimed\");\n    this.assertStarting(record);\n    this.deps.registry.activate(record.session.sessionId);\n    this.deps.observation.endAction(record.session.sessionId);\n  }\n\n  /** Accept a durable stop; aborting its caller only cancels waiting, never cleanup. */\n  async stop({ sessionId, requestId, signal }: StopOptions = {}): Promise<StopResult> {\n    if (signal?.aborted) throw abortError();\n    if (this.closing) throw new Error(\"browser plugin is unloading\");\n    const record = this.resolveStop(sessionId, requestId);\n    const stopped = record.session?.sessionId ?? \"pending browser starts\";\n    const alreadyClosed = record.stop === \"closed\";\n    const implicit = !sessionId?.trim() && requestId === undefined;\n    let admitted = false;\n    try {\n      if (!alreadyClosed || (implicit && record.defaultStopRevision === undefined))\n        this.requestCleanup(record, true, implicit);\n      admitted = true;\n      const revision = implicit ? record.defaultStopRevision : undefined;\n      if (!alreadyClosed) await waitForCleanup(this.cancel(record), signal);\n      if (signal?.aborted) throw abortError();\n      // An explicit/overlay caller, or a concurrent waiter that predates another\n      // caller's failure, must not consume that caller's default retry target.\n      if (record.defaultStopRevision === undefined || revision === record.defaultStopRevision) {\n        this.journal.records.delete(record.requestId);\n        try {\n          this.journal.save();\n        } catch (error) {\n          this.journal.records.set(record.requestId, record);\n          throw error;\n        }\n      }\n      return { stopped, requestId: record.requestId, alreadyClosed };\n    } catch (error) {\n      if (implicit && admitted) {\n        // Restore even if another waiter just acknowledged completion. Keeping\n        // this receipt ensures the failed call can never fall through to A.\n        record.defaultStopRevision = (record.defaultStopRevision ?? 0) + 1;\n        this.journal.records.set(record.requestId, record);\n        try {\n          this.journal.save();\n        } catch (saveError) {\n          console.warn(\"Browser stop retry receipt write failed\", saveError);\n        }\n      }\n      throw error;\n    }\n  }\n\n  private resolveStop(sessionId?: string, requestId?: string): StartRecord {\n    if (requestId !== undefined) {\n      if (sessionId !== undefined) throw new Error(\"Specify either session or requestId, not both\");\n      const record = this.journal.records.get(requestId);\n      if (!record) throw new Error(\"browser stop request does not belong to this plugin\");\n      return record;\n    }\n    const records = [...this.journal.records.values()];\n    const receipts = records.filter((r) => r.stop !== undefined);\n    if (sessionId?.trim()) {\n      // Prefer a previous stop even if Chrome has since reused its short ID.\n      const receipt = receipts.find((r) => r.session?.sessionId === sessionId);\n      if (receipt) return receipt;\n    } else {\n      if (receipts.length === 1) return receipts[0];\n      if (receipts.length > 1) {\n        throw new Error(\n          `Several stops await acknowledgement (${receipts.map((r) => `${r.session?.sessionId ?? \"pending start\"}: ${r.requestId}`).join(\", \")}); specify session or requestId to retry one`,\n        );\n      }\n      if (this.deps.registry.current() === undefined) {\n        const pending = records.filter((r) => r.cleanup);\n        if (pending.length === 1) return pending[0];\n        if (pending.length > 1)\n          throw new Error(\n            `Several browser starts await cleanup (${pending.map((r) => r.requestId).join(\", \")}); use list to retry cleanup or specify requestId`,\n          );\n      }\n    }\n    const id = this.deps.registry.resolveForStop(sessionId);\n    const ownedRequestId = this.deps.registry.requestFor(id);\n    const record = ownedRequestId ? this.journal.records.get(ownedRequestId) : undefined;\n    if (!record || !this.ownsRegisteredSession(record))\n      throw new Error(`browser session ${id} has no owned lifecycle request`);\n    return record;\n  }\n\n  private requestCleanup(record: StartRecord, explicitStop = false, implicit = false): void {\n    const previous = {\n      cleanup: record.cleanup,\n      stop: record.stop,\n      defaultStopRevision: record.defaultStopRevision,\n    };\n    if (record.stop !== \"closed\") {\n      record.cleanup = true;\n      if (explicitStop) record.stop = \"pending\";\n    }\n    if (implicit) record.defaultStopRevision ??= 0;\n    try {\n      this.journal.save();\n    } catch (error) {\n      if (explicitStop) {\n        // Nothing has been dispatched or made unusable yet: reject admission.\n        record.cleanup = previous.cleanup;\n        record.stop = previous.stop;\n        record.defaultStopRevision = previous.defaultStopRevision;\n        throw error;\n      }\n      // Startup/archival cleanup must continue even if the disk is unavailable.\n      // Its original ownership record still enables recovery after restart.\n      console.warn(\"Browser cleanup journal write failed\", error);\n    }\n    if (\n      record.session &&\n      record.stop !== \"closed\" &&\n      this.ownsRegisteredSession(record) &&\n      this.deps.registry.stateFor(record.session.sessionId) !== \"cleanup\"\n    ) {\n      this.deps.registry.markForCleanup(record.session.sessionId);\n      this.deps.observation.endAction(record.session.sessionId);\n    }\n    this.schedule();\n  }\n\n  async fail(record: StartRecord): Promise<void> {\n    if (!this.journal.records.has(record.requestId) || record.stop === \"closed\") return;\n    this.requestCleanup(record);\n    await this.cancel(record);\n  }\n\n  private cancel(record: StartRecord): Promise<void> {\n    const existing = this.cleaning.get(record.requestId);\n    if (existing) return existing;\n    // Publish the shared job before observation callbacks or runner hooks run.\n    const work = Promise.resolve()\n      .then(() => this.cancelOnce(record))\n      .finally(() => {\n        this.cleaning.delete(record.requestId);\n        this.schedule();\n      });\n    this.cleaning.set(record.requestId, work);\n    return work;\n  }\n\n  private async cancelOnce(record: StartRecord): Promise<void> {\n    const sessionId = this.ownsRegisteredSession(record) ? record.session?.sessionId : undefined;\n    const release = sessionId ? this.deps.observation.acquireForeground(sessionId) : undefined;\n    let actionError: string | undefined;\n    try {\n      if (sessionId) {\n        this.deps.observation.beginAction(sessionId, \"stopping\");\n        this.deps.runner.killFor(sessionId);\n      }\n      // All entry points share one job per request. Neither its queue slot nor\n      // its process belongs to the caller's abort signal or ordinary tool tag.\n      const run = () =>\n        runWithSessionBusyRetry(() =>\n          this.deps.runner.run([\"session\", \"request\", record.requestId, \"--cancel\"], {\n            timeoutMs: 30_000,\n            tag: `cleanup:${record.requestId}`,\n          }),\n        );\n      const result = sessionId ? await this.deps.queue.run(sessionId, run) : await run();\n      const status = parseBskJson(result, \"session request cancel\") as RequestStatus;\n      if (result.aborted) throw new Error(\"browser cleanup was interrupted\");\n      if (status.session) {\n        if (\n          typeof status.session.session_id !== \"string\" ||\n          typeof status.session.browser_instance_id !== \"string\"\n        )\n          throw new Error(\"Invalid browser cleanup session identity; ownership retained\");\n        if (\n          record.session &&\n          (record.session.sessionId !== status.session.session_id ||\n            record.session.browserInstanceId !== status.session.browser_instance_id)\n        )\n          throw new Error(\n            \"Browser cleanup returned a different session identity; ownership retained\",\n          );\n      }\n      if (status.state === \"closed\" || status.state === \"failed\") {\n        this.completeCleanup(record);\n        return;\n      }\n      if (status.session) {\n        record.session = {\n          sessionId: status.session.session_id,\n          browserInstanceId: status.session.browser_instance_id,\n        };\n        this.journal.save();\n        this.adopt(record);\n      }\n      throw new Error(status.cleanup_error ?? \"browser start is still being cancelled\");\n    } catch (error) {\n      actionError = error instanceof Error ? error.message.split(\"\\n\")[0] : String(error);\n      throw error;\n    } finally {\n      if (sessionId && this.ownsRegisteredSession(record))\n        this.deps.observation.endAction(sessionId, actionError);\n      release?.();\n    }\n  }\n\n  private releaseResource(record: StartRecord): void {\n    if (record.session && this.ownsRegisteredSession(record)) {\n      this.deps.registry.remove(record.session.sessionId);\n      this.deps.observation.removeSession(record.session.sessionId);\n    }\n    if (this.reserved.delete(record.requestId)) this.deps.registry.abandonStart();\n  }\n\n  private completeCleanup(record: StartRecord): void {\n    if (record.stop) {\n      record.stop = \"closed\";\n      record.cleanup = false;\n      this.releaseResource(record);\n      this.journal.save();\n    } else this.forget(record);\n  }\n\n  private forget(record: StartRecord): void {\n    this.releaseResource(record);\n    this.journal.records.delete(record.requestId);\n    this.journal.save();\n  }\n\n  private ownsRegisteredSession(record: StartRecord): boolean {\n    return (\n      record.session !== undefined &&\n      this.deps.registry.requestFor(record.session.sessionId) === record.requestId\n    );\n  }\n\n  /** Forget passive session disappearance, preserving unacknowledged stop receipts. */\n  forgetStopped(): void {\n    for (const record of this.journal.records.values()) {\n      if (!record.cleanup && !record.stop && record.session && !this.ownsRegisteredSession(record))\n        this.forget(record);\n    }\n  }\n\n  async reconcile(): Promise<void> {\n    this.forgetStopped();\n    await Promise.allSettled(\n      [...this.journal.records.values()].filter((r) => r.cleanup).map((r) => this.cancel(r)),\n    );\n  }\n\n  pendingCleanup(): number {\n    return [...this.journal.records.values()].filter((r) => r.cleanup).length;\n  }\n\n  archive(owner: string): void {\n    for (const record of this.journal.records.values()) {\n      if (record.owners.includes(owner)) void this.fail(record).catch(() => {});\n    }\n  }\n\n  private schedule(): void {\n    if (this.closing || this.timer || this.pendingCleanup() === 0) return;\n    this.timer = setTimeout(() => {\n      this.timer = undefined;\n      void this.reconcile().catch((error) => {\n        console.warn(\"Browser start reconciliation failed\", error);\n        this.schedule();\n      });\n    }, 15_000);\n    this.timer.unref();\n  }\n\n  async dispose(): Promise<void> {\n    this.closing = true;\n    if (this.timer) clearTimeout(this.timer);\n    this.deps.runner.killAll();\n    await Promise.allSettled([...this.journal.records.values()].map((r) => this.fail(r)));\n    this.journal.release();\n  }\n}\n\nfunction abortError(): Error {\n  return new DOMException(\"tool call aborted\", \"AbortError\");\n}\n\n/** Detach one waiter without cancelling shared cleanup or leaking its rejection. */\nfunction waitForCleanup(work: Promise<void>, signal?: AbortSignal): Promise<void> {\n  if (!signal) return work;\n  return new Promise((resolve, reject) => {\n    const onAbort = () => {\n      signal.removeEventListener(\"abort\", onAbort);\n      reject(abortError());\n    };\n    signal.addEventListener(\"abort\", onAbort, { once: true });\n    work.then(\n      () => {\n        signal.removeEventListener(\"abort\", onAbort);\n        if (signal.aborted) reject(abortError());\n        else resolve();\n      },\n      (error: unknown) => {\n        signal.removeEventListener(\"abort\", onAbort);\n        reject(error);\n      },\n    );\n    if (signal.aborted) onAbort();\n  });\n}\n"
    },
    {
      "path": "packages/dsh-plugin-browserskill/src/sessions.ts",
      "content": "/**\n * Tracks the bsk sessions this plugin created and the \"current\" session\n * pointer used when a tool call omits its optional `session` arg. The pointer\n * moves to whatever session was most recently started, stopped, or operated\n * on, so a model can run several browsers side by side without repeating the\n * id on every call.\n *\n * Strict ownership boundary (the bsk daemon may be shared with other agents,\n * terminals, or dsh instances): the registry ONLY ever holds sessions created\n * by this plugin's bsk_session start action. Tools cannot see or act on any\n * other session — an explicit `session` argument naming a foreign id is an\n * error, the list tool shows owned sessions only, and stop/unload cleanup\n * can never touch a session this plugin did not create.\n */\n\nexport interface TrackedSession {\n  sessionId: string;\n  /** Stable lifecycle handle, retained even if the short session ID is reused. */\n  requestId?: string;\n  browserInstanceId?: string;\n  startedAtMs: number;\n  /** Always true: only plugin-created sessions enter the registry at all. */\n  owned: boolean;\n  state: \"starting\" | \"active\" | \"cleanup\";\n}\n\ntype NewSession = Omit<TrackedSession, \"owned\" | \"state\">;\n\nexport class SessionRegistry {\n  private readonly sessions = new Map<string, TrackedSession>();\n  private currentId: string | undefined;\n  /**\n   * bsk session id → the DSH session ids that may clean it up: the agent\n   * session that started it plus every ancestor along the seed lineage, so\n   * archiving a conversation at ANY level of the chain reaps its browsers\n   * (see archive-cleanup.ts).\n   */\n  private readonly dshOwners = new Map<string, ReadonlySet<string>>();\n  /**\n   * Slots reserved by in-flight starts. reserveStart/completeStart/abandonStart\n   * run synchronously around the async spawn, so concurrent starts can never\n   * both pass the capacity check (check-and-reserve is atomic on the event loop).\n   */\n  private pendingStarts = 0;\n\n  constructor(private readonly maxSessions: number) {}\n\n  /**\n   * Reserve a start slot synchronously, BEFORE spawning.\n   * @throws when the configured concurrency cap (tracked + in-flight) is reached.\n   */\n  reserveStart(recoveredPending = 0): void {\n    if (this.sessions.size + this.pendingStarts + recoveredPending >= this.maxSessions) {\n      throw new Error(\n        `session limit reached (${this.maxSessions} concurrent sessions); ` +\n          \"stop one with bsk_session action=stop before starting another\",\n      );\n    }\n    this.pendingStarts += 1;\n  }\n\n  /** Give back a reservation after a start that never produced a session. */\n  abandonStart(): void {\n    this.pendingStarts = Math.max(0, this.pendingStarts - 1);\n  }\n\n  /**\n   * Register a freshly started session, consuming its reservation, and make\n   * it current.\n   */\n  completeStart(session: NewSession): void {\n    this.trackStart(session);\n    this.activate(session.sessionId);\n  }\n\n  /** Own a resource without exposing it to ordinary browser commands. */\n  trackStart(session: NewSession, state: \"starting\" | \"cleanup\" = \"starting\"): void {\n    this.pendingStarts = Math.max(0, this.pendingStarts - 1);\n    // Backstop only: with the reservation protocol above this never fires.\n    if (!this.sessions.has(session.sessionId) && this.sessions.size >= this.maxSessions) {\n      throw new Error(\n        `session limit reached (${this.maxSessions} concurrent sessions); ` +\n          \"stop one with bsk_session action=stop before starting another\",\n      );\n    }\n    this.sessions.set(session.sessionId, { ...session, owned: true, state });\n  }\n\n  /** Publish only after initialization and the daemon claim have succeeded. */\n  activate(sessionId: string): void {\n    const session = this.sessions.get(sessionId);\n    if (session?.state !== \"starting\")\n      throw new Error(\"browser start is no longer awaiting activation\");\n    session.state = \"active\";\n    this.touch(sessionId);\n  }\n\n  markForCleanup(sessionId: string): void {\n    const session = this.sessions.get(sessionId);\n    if (!session) return;\n    session.state = \"cleanup\";\n    if (this.currentId === sessionId) this.selectCurrent();\n  }\n\n  private selectCurrent(): void {\n    this.currentId = [...this.sessions.values()]\n      .filter((s) => s.state === \"active\")\n      .at(-1)?.sessionId;\n  }\n\n  isUsable(sessionId: string): boolean {\n    return this.sessions.get(sessionId)?.state === \"active\";\n  }\n\n  stateFor(sessionId: string): TrackedSession[\"state\"] | undefined {\n    return this.sessions.get(sessionId)?.state;\n  }\n\n  assertUsable(sessionId: string, toolName: string): void {\n    if (!this.isOwned(sessionId)) throw this.foreignError(sessionId, toolName);\n    if (!this.isUsable(sessionId)) {\n      const reason = this.stateFor(sessionId) === \"cleanup\" ? \"awaiting cleanup\" : \"not ready\";\n      throw new Error(\n        `${toolName}: session \"${sessionId}\" is ${reason}; only stop is available until the session is active`,\n      );\n    }\n  }\n\n  /** Forget a session; falls back to the most recent remaining one. */\n  remove(sessionId: string): void {\n    this.sessions.delete(sessionId);\n    this.dshOwners.delete(sessionId);\n    if (this.currentId === sessionId) {\n      this.selectCurrent();\n    }\n  }\n\n  /**\n   * Record which DSH conversation(s) a freshly started bsk session belongs\n   * to (the starting agent's session plus its ancestors). No-op without ids\n   * — e.g. a start whose caller carried no agent identity.\n   */\n  trackOwner(sessionId: string, dshSessionIds: readonly string[]): void {\n    if (dshSessionIds.length === 0 || !this.sessions.has(sessionId)) return;\n    this.dshOwners.set(sessionId, new Set(dshSessionIds));\n  }\n\n  /** bsk session ids owned by the given DSH conversation (or its descendants). */\n  ownedByDsh(dshSessionId: string): string[] {\n    const owned: string[] = [];\n    for (const [sessionId, owners] of this.dshOwners) {\n      if (owners.has(dshSessionId)) owned.push(sessionId);\n    }\n    return owned;\n  }\n\n  /** The DSH conversation ids owning one bsk session (empty when untracked). */\n  dshOwnersOf(sessionId: string): string[] {\n    return [...(this.dshOwners.get(sessionId) ?? [])];\n  }\n\n  /** Mark an owned session as most recently used (recency order refresh). */\n  private touch(sessionId: string): void {\n    const existing = this.sessions.get(sessionId);\n    if (existing === undefined) return;\n    this.sessions.delete(sessionId);\n    this.sessions.set(sessionId, existing);\n    this.currentId = sessionId;\n  }\n\n  /** The current session id, if any. */\n  current(): string | undefined {\n    return this.currentId;\n  }\n\n  /** Owned sessions in least- to most-recently-used order. */\n  list(): TrackedSession[] {\n    return [...this.sessions.values()];\n  }\n\n  /** Ids of owned sessions — the exact set unload cleanup is allowed to stop. */\n  ownedIds(): string[] {\n    return this.list()\n      .filter((session) => session.owned)\n      .map((session) => session.sessionId);\n  }\n\n  /** Whether the session was created by this plugin. */\n  isOwned(sessionId: string): boolean {\n    return this.sessions.get(sessionId)?.owned === true;\n  }\n\n  requestFor(sessionId: string): string | undefined {\n    return this.sessions.get(sessionId)?.requestId;\n  }\n\n  size(): number {\n    return this.sessions.size;\n  }\n\n  /** Shared not-yours error for foreign or unknown session ids. */\n  private foreignError(sessionId: string, toolName: string): Error {\n    return new Error(\n      `${toolName}: session \"${sessionId}\" does not belong to this plugin — only sessions ` +\n        \"created by bsk_session action=start are visible and operable here\",\n    );\n  }\n\n  /**\n   * Resolve the session a tool call acts on: an explicit `session` argument\n   * must name an owned session (and becomes current); omitted falls back to\n   * the current session. Foreign ids are rejected, never adopted.\n   * @throws on foreign/unknown ids, or when no session exists.\n   */\n  resolve(explicit: string | undefined, toolName: string): string {\n    if (explicit !== undefined && explicit.trim().length > 0) {\n      this.assertUsable(explicit, toolName);\n      this.touch(explicit);\n      return explicit;\n    }\n    const current = this.current();\n    if (current === undefined) {\n      throw new Error(\n        `${toolName} needs a session but none is active — use bsk_session action=start`,\n      );\n    }\n    this.touch(current);\n    return current;\n  }\n\n  /**\n   * Stop can also reach starting/cleanup resources. If no usable session is\n   * current, default to the most recent owned resource so cleanup is retryable.\n   * A rejected stop never moves the current pointer.\n   */\n  resolveForStop(explicit: string | undefined): string {\n    const candidate =\n      explicit !== undefined && explicit.trim().length > 0\n        ? explicit\n        : (this.current() ?? this.list().at(-1)?.sessionId);\n    if (candidate === undefined) {\n      throw new Error(\n        \"bsk_session action=stop needs a session but none is active — use action=start first\",\n      );\n    }\n    if (!this.isOwned(candidate)) throw this.foreignError(candidate, \"bsk_session(action=stop)\");\n    return candidate;\n  }\n}\n"
    },
